function scoreEventTypeChange(n){console.log(n.value);n.value==="normal_goal"?$("#scoreAssist").removeClass("d-none"):$("#scoreAssist").addClass("d-none")}function scorePeriodTypeChange(n){console.log(n.value);n.value==="extra_time"?$("#scoreExtratime").removeClass("d-none"):$("#scoreExtratime").addClass("d-none")}function cardPeriodTypeChange(n){console.log(n.value);n.value==="overtime"?$("#cardExtratime").removeClass("d-none"):$("#cardExtratime").addClass("d-none")}function OpenModalPopUp(n){var t=JSON.parse(n);$(".reservationDay").text(JSON.stringify(t,null,"\t"));$("#logRequest").modal()}$(document).ready(function(){$("#example").DataTable();$("#mathes-table").DataTable()});